// ─── File: SolidDemo.java ───
package com.bank.solid;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class SolidDemo {
    private static final Logger log = Logger.getLogger("SOLID");
    public static void main(String[] args) {
        // Dependency Inversion: service depends on the interface
        InterestService savings = new InterestService(new SavingsInterest());
        InterestService fd = new InterestService(new FixedDepositInterest());
        log.info(() -> "Rajesh savings interest = " + savings.annualInterest(new BigDecimal("1000000")));
        log.info(() -> "Priya FD interest = " + fd.annualInterest(new BigDecimal("250000")));
    }
}

// ─── strategy/InterestStrategy.java ───
interface InterestStrategy { BigDecimal interest(BigDecimal balance); }

class SavingsInterest implements InterestStrategy {        // Open/Closed: new class, no edits
    public BigDecimal interest(BigDecimal b) { return b.multiply(new BigDecimal("0.04")); }
}
class FixedDepositInterest implements InterestStrategy {    // Liskov: substitutable
    public BigDecimal interest(BigDecimal b) { return b.multiply(new BigDecimal("0.07")); }
}

// ─── service/InterestService.java ───
class InterestService {                                     // Single Responsibility: only interest
    private final InterestStrategy strategy;
    InterestService(InterestStrategy strategy) { this.strategy = strategy; }
    BigDecimal annualInterest(BigDecimal balance) { return strategy.interest(balance); }
}
